const BORDER_SRC = "data:image/png;base64,";
const LOGO_SRC   = "data:image/png;base64,";
const STAMP_SRC  = "data:image/png;base64,";

const els = id => document.getElementById(id);
let offerType = "internship-paid";

document.querySelectorAll(".type-switch button").forEach(btn=>{
  btn.addEventListener("click", ()=>{
    document.querySelectorAll(".type-switch button").forEach(b=>b.classList.remove("active"));
    btn.classList.add("active");
    offerType = btn.dataset.type;
    syncFieldVisibility();
    render();
  });
});

function syncFieldVisibility(){
  const isInternship = offerType !== "job";
  els("durationBlock").style.display = isInternship ? "block" : "none";
  els("joiningBlock").style.display = isInternship ? "none" : "block";
  els("stipendBlock").style.display = (offerType === "internship-paid") ? "block" : "none";
  els("salaryBlock").style.display = (offerType === "job") ? "block" : "none";
  els("eligibilityBlock").style.display = isInternship ? "block" : "none";
}

function fmtDate(val){
  if(!val) return "__/__/____";
  const d = new Date(val + "T00:00:00");
  return `${String(d.getDate()).padStart(2,"0")}/${String(d.getMonth()+1).padStart(2,"0")}/${d.getFullYear()}`;
}
function escapeHtml(str){ return String(str).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); }
function linesToList(text){ return text.split("\n").map(l=>l.trim()).filter(Boolean).map(l=>`<li>${escapeHtml(l)}</li>`).join(""); }

function calcDurationText(){
  const s = els("startDate").value, e = els("endDate").value;
  if(!s || !e) return `${fmtDate(s)} – ${fmtDate(e)}`;
  const start = new Date(s+"T00:00:00"), end = new Date(e+"T00:00:00");
  const days = Math.round((end-start)/86400000) + 1;
  const text = `${fmtDate(s)} – ${fmtDate(e)} (${days > 0 ? days : 0} Days)`;
  els("durationPreview").textContent = "Preview: " + text;
  return text;
}

/* ---------- build content blocks ---------- */
function buildHeaderHtml(){
  const l1 = els("addrLine1").value, l2 = els("addrLine2").value;
  const email = els("addrEmail").value, web = els("addrWeb").value;
  return `
  <div class="letter-header">
    <div class="logo-mini"><img src="${LOGO_SRC}" alt="Arox Tech logo"></div>
    <div class="addr-text">
      <b>Arox Tech</b>
      ${escapeHtml(l1)}<br>${escapeHtml(l2)}<br>
      Email: ${escapeHtml(email)}<br>Website: ${escapeHtml(web)}
    </div>
  </div>`;
}

function buildBlocks(){
  const type = offerType;
  const isInternship = type !== "job";
  const isPaidIntern = type === "internship-paid";

  const offerNo = els("offerNo").value || "—";
  const dateStr = fmtDate(els("letterDate").value);
  const salutation = els("salutation").value;
  const name = els("candidateName").value || "Candidate Name";
  const position = els("position").value || "—";
  const department = els("department").value || "—";
  const reportingTo = els("reportingTo").value || "—";
  const location = els("location").value || "—";
  const workingDays = els("workingDays").value || "—";
  const workingHours = els("workingHours").value || "—";
  const companyName = els("companyName").value || "Arox Tech";
  const signatoryName = els("signatoryName").value.trim();
  const signatoryDesignation = els("signatoryDesignation").value || "HR Manager";

  const docTitle = isInternship ? "INTERNSHIP OFFER LETTER" : "JOB OFFER LETTER";
  const subject = isInternship ? `Offer of Internship – ${position}` : `Offer of Employment – ${position}`;
  const openingPara = isInternship
    ? `We are pleased to offer you an internship at ${companyName} as a ${position}. This internship is designed to provide practical industry experience, hands-on project exposure, and professional mentorship.`
    : `We are pleased to offer you the position of ${position} at ${companyName}. We believe your skills and experience will make a valuable contribution to our team, and we look forward to having you on board.`;

  function row(label, value){ return `<tr><td>${escapeHtml(label)}</td><td>${escapeHtml(String(value))}</td></tr>`; }
  let rows = row("Position", position) + row("Department", department);
  if(isInternship){
    rows += row("Duration", calcDurationText());
  } else {
    rows += row("Date of Joining", fmtDate(els("joiningDate").value));
    rows += row("Employment Type", els("employmentType").value);
    const probation = els("probation").value.trim();
    if(probation) rows += row("Probation Period", probation);
  }
  rows += row("Location", location) + row("Working Days", workingDays) + row("Working Hours", workingHours);
  if(isPaidIntern){
    rows += row("Stipend", els("stipendAmount").value || "—");
  } else if(type === "job"){
    const salary = els("salaryAmount").value.trim();
    if(salary) rows += row("CTC / Salary", salary);
  }
  rows += row("Reporting To", reportingTo);

  const blocks = [];

  blocks.push(`
    <div class="doc-title">${docTitle}</div>
    <div class="meta-row"><span><b>Offer Letter No.:</b> ${escapeHtml(offerNo)}</span><span><b>Date:</b> ${dateStr}</span></div>
    <div class="addr-block"><span class="to-label">To,</span><br>${salutation} ${escapeHtml(name)}</div>
    <div class="subject-line"><b>Subject:</b> ${escapeHtml(subject)}</div>
    <div class="greet">Dear ${escapeHtml(name.split(" ")[0])},</div>
    <div class="para">${escapeHtml(openingPara)}</div>
  `);

  blocks.push(`
    <table class="detail-table">
      <caption>${isInternship ? "Internship Details" : "Employment Details"}</caption>
      ${rows}
    </table>
  `);

  const rolesList = linesToList(els("roles").value);
  blocks.push(`
    <div class="section-title">Roles &amp; Responsibilities</div>
    <p class="para" style="margin-bottom:6px;">${isInternship ? "During your internship, you will be expected to:" : "In this role, you will be expected to:"}</p>
    <ul class="doc-list">${rolesList}</ul>
  `);

  if(els("includeEval").checked){
    blocks.push(`
      <div class="section-title">Performance Evaluation</div>
      <p class="para" style="margin-bottom:6px;">Your performance will be assessed based on:</p>
      <ul class="doc-list">${linesToList(els("evalCriteria").value)}</ul>
    `);
  }

  if(isInternship && els("includeEligibility").checked){
    blocks.push(`<div class="note-box">${escapeHtml(els("eligibilityText").value)}</div>`);
  }



  blocks.push(`
    <div class="section-title">Terms &amp; Conditions</div>
    <ul class="doc-list">${linesToList(els("terms").value)}</ul>
  `);

  const stampHtml = els("includeStamp").checked
    ? `<img src="${STAMP_SRC}" alt="Signature & seal" style="height:26mm;width:auto;mix-blend-mode:multiply;opacity:.95;display:block;margin-bottom:4px;">`
    : "";

  blocks.push(`
    <div class="section-title">Acceptance</div>
    <div class="accept-block">
      If you accept the terms and conditions outlined above, please sign and return a copy of this letter to confirm your acceptance.<br><br>
      We are glad to welcome you to ${escapeHtml(companyName)} and look forward to a ${isInternship ? "productive and rewarding internship" : "long and successful working relationship"}.<br><br>
      Sincerely,<br>HR Department<br>${escapeHtml(companyName)}
    </div>
  `);

  blocks.push(`
    <div style="margin-top: 30px; text-align: left;">
      ${stampHtml}
      <div style="font-size:12.5px; font-weight:600; color:var(--navy); margin-bottom:4px;">Signature &amp; Seal</div>
      <div style="font-size:12px; color:var(--ink);">
        Praveen<br>
        Founder, Arox Tech
      </div>
    </div>
  `);

  return { header: buildHeaderHtml(), blocks, offerNo, companyName };
}

/* ---------- measuring & pagination ---------- */
function makeMeasureShell(){
  const shell = document.createElement("div");
  shell.className = "page";
  shell.style.position = "fixed";
  shell.style.left = "-9999px";
  shell.style.top = "0";
  shell.style.visibility = "hidden";
  document.body.appendChild(shell);
  return shell;
}
function getGeometry(){
  const shell = makeMeasureShell();
  const cs = getComputedStyle(shell);
  const padTop = parseFloat(cs.paddingTop), padBottom = parseFloat(cs.paddingBottom);
  const padLeft = parseFloat(cs.paddingLeft), padRight = parseFloat(cs.paddingRight);
  const totalH = shell.getBoundingClientRect().height;
  const totalW = shell.getBoundingClientRect().width;
  document.body.removeChild(shell);
  return {
    contentWidth: totalW - padLeft - padRight,
    contentHeight: totalH - padTop - padBottom - 14 // small safety buffer
  };
}
function measureHeight(html, width){
  const wrap = document.createElement("div");
  wrap.style.position = "fixed";
  wrap.style.left = "-9999px";
  wrap.style.top = "0";
  wrap.style.visibility = "hidden";
  wrap.style.width = width + "px";
  wrap.innerHTML = html;
  document.body.appendChild(wrap);
  const h = wrap.getBoundingClientRect().height;
  document.body.removeChild(wrap);
  return h;
}
function paginate(headerHtml, blocks){
  const geo = getGeometry();
  const headerH = measureHeight(headerHtml, geo.contentWidth);
  const pages = [];
  let current = [], currentH = 0, isFirst = true;
  blocks.forEach(b=>{
    const h = measureHeight(b, geo.contentWidth);
    const avail = isFirst ? geo.contentHeight - headerH : geo.contentHeight;
    if(current.length > 0 && currentH + h > avail){
      pages.push(current); current = []; currentH = 0; isFirst = false;
    }
    current.push(b); currentH += h;
  });
  pages.push(current);
  return pages;
}

/* ---------- render ---------- */
function render(){
  const { header, blocks, offerNo, companyName } = buildBlocks();
  const pages = paginate(header, blocks);
  const total = pages.length;
  const container = els("pagesContainer");
  container.innerHTML = "";
  pages.forEach((blockArr, idx)=>{
    const label = document.createElement("div");
    label.className = "page-label";
    label.textContent = `Page ${idx+1} of ${total}`;
    container.appendChild(label);

    const pageDiv = document.createElement("div");
    pageDiv.className = "page";
    pageDiv.contentEditable = "true";
    let inner = idx===0 ? header : "";
    inner += blockArr.join("");
    inner += `<div class="foot-brand">${escapeHtml(companyName)} &middot; Offer No. ${escapeHtml(offerNo)} &middot; Page ${idx+1} of ${total}</div>`;
    pageDiv.innerHTML = inner;
    container.appendChild(pageDiv);
  });
}

document.querySelectorAll(".control-panel input, .control-panel select, .control-panel textarea")
  .forEach(el => el.addEventListener("input", render));

els("printBtn").addEventListener("click", ()=>window.print());

els("resetBtn").addEventListener("click", ()=>{
  if(confirm("Reset all fields to default sample values?")) location.reload();
});

els("downloadBtn").addEventListener("click", downloadPDF);

async function downloadPDF(){
  const overlay = els("loadingOverlay");
  overlay.classList.remove("hidden");
  await new Promise(r=>setTimeout(r, 80));
  try{
    if(document.fonts && document.fonts.ready) await document.fonts.ready;
    await new Promise(r=>setTimeout(r, 150));
    const { jsPDF } = window.jspdf;
    const pdf = new jsPDF("p", "mm", "a4");
    const pageEls = document.querySelectorAll("#pagesContainer .page");
    for(let i=0;i<pageEls.length;i++){
      const canvas = await html2canvas(pageEls[i], {
        scale: 2.2, useCORS: true, backgroundColor: "#ffffff", logging: false,
        windowWidth: pageEls[i].scrollWidth, windowHeight: pageEls[i].scrollHeight
      });
      const imgData = canvas.toDataURL("image/png", 1.0);
      if(i>0) pdf.addPage();
      pdf.addImage(imgData, "PNG", 0, 0, 210, 297, undefined, "FAST");
    }
    const nameSafe = (els("candidateName").value || "Candidate").replace(/[^a-z0-9]+/gi, "_");
    pdf.save(`Offer_Letter_${nameSafe}.pdf`);
  }catch(err){
    alert("Something went wrong while generating the PDF: " + err.message);
    console.error(err);
  }
  overlay.classList.add("hidden");
}

(function initDates(){
  const today = new Date().toISOString().slice(0,10);
  els("letterDate").value = today;
  els("startDate").value = today;
  const end = new Date(); end.setDate(end.getDate()+59);
  els("endDate").value = end.toISOString().slice(0,10);
  els("joiningDate").value = today;
})();

syncFieldVisibility();
render();

// ERP Integration: postMessage API for Live Document Hub
window.addEventListener('message', (event) => {
  const { type, data } = event.data || {};
  if (type === 'UPDATE_DATA') {
    if (data.candidateName) {
      const nameInput = document.getElementById('candidateName');
      if (nameInput) nameInput.value = data.candidateName;
    }
    if (data.roleTitle || data.position) {
      const positionInput = document.getElementById('position');
      if (positionInput) positionInput.value = data.roleTitle || data.position;
    }
    if (data.location) {
      const locationInput = document.getElementById('location');
      if (locationInput) locationInput.value = data.location;
    }
    if (data.startDate) {
      const startInput = document.getElementById('startDate');
      if (startInput) startInput.value = data.startDate.split('T')[0];
    }
    if (data.endDate) {
      const endInput = document.getElementById('endDate');
      if (endInput) endInput.value = data.endDate.split('T')[0];
    }
    if (data.stipendAmount) {
      const stipendInput = document.getElementById('stipendAmount');
      if (stipendInput) stipendInput.value = data.stipendAmount;
    }
    // Refresh the preview
    if (typeof render === 'function') render();
  } else if (type === 'EXPORT_PDF') {
    if (typeof downloadPDF === 'function') downloadPDF();
  }
});

